public class Program
{
    public static string busiest_doctor(List<Appointment> appts)
    {
        if (appts == null || appts.Count == 0)
        {
            return "";
        }

        var doctorCounts = appts
            .GroupBy(app => app.Doctor)
            .Select(group => new DoctorCount
            {
                Doctor = group.Key,
                Count = group.Count()
            });

        var busiestDoctor = doctorCounts
            .OrderByDescending(count => count.Count)
            .FirstOrDefault();

        return busiestDoctor != null ? busiestDoctor.Doctor.Name : "";
    }

    public static void Main(string[] args)
    {
        // Example usage
        var appointments = new List<Appointment>
        {
            new Appointment { Doctor = new Doctor { Name = "Dr. Smith" }, Patient = new Patient { Name = "John Doe" } },
            new Appointment { Doctor = new Doctor { Name = "Dr. Johnson" }, Patient = new Patient { Name = "Jane Smith" } },
            new Appointment { Doctor = new Doctor { Name = "Dr. Smith" }, Patient = new Patient { Name = "Jane Doe" } }
        };

        Console.WriteLine(busiest_doctor(appointments)); // Output: Dr. Smith
    }
}

