public class KiteNet
{
    public static string Winner(List<string> votes)
    {
        if (votes == null || votes.Count == 0)
        {
            return null;
        }

        var voteCount = votes.GroupBy(vote => vote)
                              .ToDictionary(group => group.Key, group => group.Count());

        int maxVotes = voteCount.Values.Max();

        return voteCount.FirstOrDefault(pair => pair.Value == maxVotes)?.Key;
    }
}

