class VoteAnalysis
{
    public static Dictionary<string, decimal> Percentages(List<string> votes)
    {
        if (votes.Count == 0)
        {
            return new Dictionary<string, decimal>();
        }

        int totalVotes = votes.Count;
        Dictionary<string, decimal> percentages = votes
            .GroupBy(vote => vote)
            .ToDictionary(group => group.Key, group => (decimal)group.Count() / totalVotes * 100);

        foreach (var pair in percentages)
        {
            pair.Value = Math.Round(pair.Value, 2);
        }

        return percentages;
    }
}

