public class KiteNet
{
    public static List<string> TiedVotes(List<string> votes)
    {
        if (votes.Count == 0)
        {
            return new List<string>();
        }

        var voteCount = votes.GroupBy(vote => vote)
                              .ToDictionary(group => group.Key, group => group.Count());

        var maxVotes = voteCount.Values.Max();

        return voteCount.Where(pair => pair.Value == maxVotes)
                         .Select(pair => pair.Key)
                         .OrderBy(candidate => candidate)
                         .ToList();
    }
}

