public class PartyVotesProcessor
{
    public PartyWinner ProcessVotes(List<PartyVotes> votes)
    {
        if (votes == null || votes.Count == 0)
        {
            return new PartyWinner { WinningParty = null };
        }

        var partyVotesCount = votes.GroupBy(vote => vote.Party)
                                  .ToDictionary(group => group.Key, group => group.Sum(vote => vote.Votes));

        int maxVotes = partyVotesCount.Values.Max();

        Party? winningParty = partyVotesCount.FirstOrDefault(pair => pair.Value == maxVotes)?.Key;

        return new PartyWinner { WinningParty = winningParty };
    }
}

