type Appointment = record(patient: str, doctor: str, scheduled: int, seen: int)

fn waiting_minutes(a: Appointment) -> int {
    if (a.seen <= a.scheduled) {
        0
    } else {
        a.seen - a.scheduled
    }
}

fun countForDoctor(appts: List<Appointment>, doctor: String): Int {
    return appts.filter { it.doctor == doctor }.count()
}

fun patients_for_doctor(appts: List<Appointment>, doctor: String): List<String> {
    return appts.filter { it.doctor == doctor }
                  .sortedBy { it.scheduled }
                  .map { it.patient }
}

type Appointment = record(patient: str, doctor: str, scheduled: int, seen: int)

fn waiting_minutes(a: Appointment) -> int as max(0, a.seen - a.scheduled)

fn average_wait(appts: list<Appointment>) -> dec as if (appts.isEmpty()) 0.0 else sum(appts.map { it.waiting_minutes() }) / appts.size

data class Appointment(val patient: String, val doctor: String, val scheduled: Int, val seen: Int)

fun waiting_minutes(a: Appointment): Int = max(0, a.seen - a.scheduled)

fun longest_wait_patient(appts: List<Appointment>): String? {
    if (appts.isEmpty()) return null
    var maxWait = 0
    var longestPatient = ""
    for (appt in appts) {
        val wait = waiting_minutes(appt)
        if (wait > maxWait) {
            maxWait = wait
            longestPatient = appt.patient
        }
    }
    return longestPatient
}

