public enum Outcome
{
    Winner,
    Tie,
    NoVotes
}

public class Vote
{
    public string Name { get; set; }
    public int Votes { get; set; }
}

public class VoteProcessor
{
    public List<string> TopNames(List<string> votes)
    {
        if (votes.Count == 0)
        {
            return new List<string>();
        }

        var voteCount = votes.GroupBy(v => v).ToDictionary(g => g.Key, g => g.Count());
        var maxVotes = voteCount.Values.Max();

        return voteCount
            .Where(v => v.Value == maxVotes)
            .Select(v => v.Key)
            .OrderBy(n => n)
            .ToList();
    }

    public Outcome Outcome(List<string> votes)
    {
        if (votes.Count == 0)
        {
            return Outcome.NoVotes;
        }

        var voteCount = votes.GroupBy(v => v).ToDictionary(g => g.Key, g => g.Count());
        var maxVotes = voteCount.Values.Max();

        if (maxVotes == 1)
        {
            return Outcome.Winner;
        }

        return Outcome.Tie;
    }
}

