class Kite
{
    public static int Margin(List<string> votes)
    {
        if (votes.Count < 2)
        {
            return 0;
        }

        var voteCounts = votes.GroupBy(vote => vote)
                              .ToDictionary(group => group.Key, group => group.Count());

        var highestCount = voteCounts.Values.Max();
        var secondHighestCount = voteCounts.Values.Where(count => count < highestCount).Max();

        return highestCount - secondHighestCount;
    }

    private static int VoteCount(List<string> votes, string candidate)
    {
        return votes.Count(vote => vote == candidate);
    }
}

