fun leading_percentage(votes: List<String>): Decimal {
    if (votes.isEmpty()) return Decimal.ZERO

    val voteCounts = votes.groupBy { it }.mapValues { it.size }
    val maxCount = voteCounts.values.maxOrNull() ?: 0

    return maxCount.toBigDecimal() / votes.size.toBigDecimal() * 100
}

data class ElectionResult(val winner: String? = null, val count: Int, val tie: Boolean = false)

fun result(votes: List<String>): ElectionResult {
    if (votes.isEmpty()) {
        return ElectionResult(null, 0, false)
    }

    val voteCount = votes.groupingBy { it }.mapValues { it.size }.toMap()
    val maxCount = voteCount.values.maxOrNull() ?: 0

    val winner = voteCount.keys.find { voteCount[it] == maxCount }
    val tie = maxCount > 1

    return ElectionResult(winner, maxCount, tie)
}

