type Candidate = record(name: str, party: str)

fn count_by_party(votes: list<Candidate>) -> map<str, int> {
    if (votes.isEmpty()) {
        return map<str, int>()
    }

    var partyCount = map<str, int>()
    for (vote in votes) {
        partyCount[vote.party] = partyCount[vote.party] ?: 0 + 1
    }

    return partyCount
}

type Party = enum(Red, Blue, Green)
type Vote = record(voter: str, party: Party)

fun party_winner(votes: list<Vote>): Party? {
    if (votes.isEmpty()) return null

    val partyVotes = votes.groupBy { it.party }
    val maxVotes = partyVotes.values.maxOrNull() ?: 0

    partyVotes.forEach { (party, votes) ->
        if (votes.size == maxVotes) return party
    }

    return null
}

data class Vote(val candidate: String, val district: String)

fun districtWinner(votes: List<Vote>, district: String): String {
    val votesInDistrict = votes.filter { it.district == district }
    if (votesInDistrict.isEmpty()) return ""

    val voteCount = votesInDistrict.groupBy { it.candidate }.mapValues { it.size }
    val maxVotes = voteCount.values.maxOrNull() ?: 0

    val candidatesWithMaxVotes = voteCount.filter { it.value == maxVotes }.map { it.key }

    return candidatesWithMaxVotes.minOrNull() ?: ""
}

