public class FareCalculator
{
    public decimal Fare(int zone, Rider rider)
    {
        decimal baseFare = zone switch
        {
            1 => 2.5m,
            2 => 3.0m,
            3 => 4.5m,
            _ => 6.0m
        };

        decimal fare;
        switch (rider)
        {
            case Rider.Child:
                fare = baseFare / 2;
                break;
            case Rider.Senior:
                fare = baseFare * 0.7m;
                break;
            default:
                fare = baseFare;
                break;
        }

        return Math.Round(fare, 2);
    }
}

