fun base_fare(zone: int): dec = when (zone) {
    1 -> 2.5
    2 -> 3.0
    3 -> 4.5
    else -> 6.0
}

fun trip_fare(trip: Trip): dec {
    val fare = trip.stops.map { base_fare(it.zone) }.sum()
    val adultCount = trip.stops.count { it.rider == Rider.Adult }
    val childCount = trip.stops.count { it.rider == Rider.Child }
    val seniorCount = trip.stops.count { it.rider == Rider.Senior }

    return when {
        adultCount > 0 -> fare * adultCount * 2
        childCount > 0 -> fare * childCount * 0.5
        seniorCount > 0 -> fare * seniorCount * 0.7
        else -> fare
    }.round(2)
}

