fun weeklyPay(entries: List<Entry>, name: String): Double {
    val entriesForName = entries.filter { it.name == name }
    if (entriesForName.isEmpty()) return 0.0

    val regularHours = entriesForName.filter { it.hours <= 40.0 }.sumOf { it.hours * it.rate }
    val overtimeHours = entriesForName.filter { it.hours > 40.0 }.sumOf { (it.hours - 40.0) * it.rate * 1.5 }

    return regularHours + overtimeHours
}

