    val totalEntries = entries.groupBy { it.name }
    return totalEntries.map { (name, entries) ->
        Total(name, entries.sumOf { it.hours }, entries.sumOf { it.hours - 40.0 })
    }
}

type Entry = record(name: str, hours: dec, rate: dec)
type Payroll = record(name: str, hours: dec, pay: dec)

fun weekly_pay(entries: list<Entry>, name: str): dec {
    var totalHours = 0.0
    var pay = 0.0
    for (entry in entries) {
        if (entry.name == name) {
            totalHours += entry.hours
            pay += entry.hours * entry.rate
        }
    }
    if (totalHours > 40.0) {
        pay += (totalHours - 40.0) * entry.rate * 1.5
    }
    return pay
}

fun payroll(entries: list<Entry>): list<Payroll> {
    val result = mutableListOf<Payroll>()
    val nameToHours = mutableMapOf<String, Double>()
    for (entry in entries) {
        nameToHours[entry.name] = (nameToHours[entry.name] ?: 0.0) + entry.hours
    }
    for (name in nameToHours.keys) {
        result.add(Payroll(name = name, hours = nameToHours[name]!!, pay = weekly_pay(entries, name)))
    }
    return result
}

