type Shift = record(person: str, rate: dec, hours: dec)

fun pay(shift: Shift, overtime_multiplier: dec): dec {
    val basePay = shift.rate * min(shift.hours, 40.0)
    val overtimePay = (shift.hours - 40.0) * shift.rate * overtime_multiplier
    return basePay + overtimePay
}

type Shift = record(person: str, rate: dec, hours: dec)

fun weekly_pay(shifts: List<Shift>, overtime_multiplier: dec): dec {
    fun pay(shift: Shift, overtime_multiplier: dec): dec {
        val basePay = shift.rate * shift.hours
        val overtimePay = if (shift.hours > 40) (shift.hours - 40) * shift.rate * overtime_multiplier else 0
        return basePay + overtimePay
    }

    return shifts.map { pay(it, overtime_multiplier) }.sum()
}

type Shift = record(
    person: str,
    rate: dec,
    hours: dec
)

fun shift_pay(shift: Shift, overtime_multiplier: dec): dec {
    val basePay = shift.rate * min(shift.hours, 40.0)
    val overtimePay = max(shift.hours - 40.0, 0.0) * shift.rate * overtime_multiplier
    return basePay + overtimePay
}

fun pay_by_person(shifts: List<Shift>, overtime_multiplier: dec): Map<str, dec> {
    val payMap = mutableMapOf<str, dec>()
    for (shift in shifts) {
        val pay = shift_pay(shift, overtime_multiplier)
        payMap[shift.person] = payMap.getOrDefault(shift.person, 0.0) + pay
    }
    return payMap
}

