type Weekly = record(regular: dec, overtime: dec)

fun split_hours(hours: List<dec>, limit: dec): Weekly {
    val result = Weekly(regular = 0.0, overtime = 0.0)
    var currentRegular = 0.0
    var currentOvertime = 0.0

    for (hour in hours) {
        if (currentRegular + hour <= limit) {
            currentRegular += hour
        } else {
            result.regular += currentRegular
            result.overtime += hour - currentRegular
            currentRegular = hour
        }
    }

    result.regular += currentRegular
    result.overtime += currentOvertime

    return result
}

