    return timesheets.map { timesheet ->
        PayLine(
            name = timesheet.name,
            pay = timesheet.hours.mapIndexed { index, hour ->
                if (hour <= limit) {
                    hour * timesheet.rate
                } else {
                    (hour - limit) * timesheet.rate * 1.5 + limit * timesheet.rate
                }
            }.sum()
        )
    }
}

