fun mergeIngredients(items: List<Ingredient>): List<Ingredient> {
    val merged = mutableMapOf<String, Ingredient>()
    items.forEach { ingredient ->
        if (merged.containsKey(ingredient.name)) {
            merged[ingredient.name] = Ingredient(ingredient.name, merged[ingredient.name].qty + ingredient.qty)
        } else {
            merged[ingredient.name] = ingredient
        }
    }
    return merged.values.toList()
}

