    val fromZone = zone_of(stops, trip.from)
    val toZone = zone_of(stops, trip.to)
    val fare = when {
        fromZone == toZone -> fare(fromZone)
        else -> fare(fromZone) + fare(toZone)
    }
    return fare
}

