}

fun trip_fare(stops: list<Stop>, trip: Trip) -> dec {
    val fromZone = zone_of(stops, trip.from)
    val toZone = zone_of(stops, trip.to)
    val fare = when {
        fromZone == toZone -> 7.5
        fromZone > toZone -> 5.0
        else -> 3.5
    }
    return fare * trip.arrive - trip.depart
}

