public class StopFinder
{
    public static int StopsBetween(List<string> stops, string start, string finish)
    {
        if (string.IsNullOrEmpty(start) || string.IsNullOrEmpty(finish))
        {
            return 0;
        }

        int startIndex = stops.IndexOf(start);
        int endIndex = stops.IndexOf(finish);

        if (startIndex == -1 || endIndex == -1 || startIndex > endIndex)
        {
            return 0;
        }

        return endIndex - startIndex + 1;
    }
}

